def subtotal(items):
    return sum(i["price"] * i["qty"] for i in items)

def discount(total, code):
    if code == "SAVE10":
        return total * 0.1
    if code == "SAVE20" and total >= 100:
        return total * 0.2
    return 0

def total(items, code=None, tax=0.14):
    s = subtotal(items)
    d = discount(s, code)
    return round((s - d) * (1 + tax), 2)
