"""Shopping cart totals."""


def subtotal(items):
    """Sum of price * qty for every item."""
    return sum(i["price"] * i["qty"] for i in items)


def discount(total, code):
    """SAVE10 = 10% off, SAVE20 = 20% off (only for totals of 100 or more), else nothing."""
    if code == "SAVE10":
        return total * 0.1
    if code == "SAVE20" and round(total, 2) >= 100:
        return total * 0.2
    return 0


def total(items, code=None, tax=0.14):
    """Subtotal minus discount, then tax added on the discounted amount; rounded to 2 places."""
    s = subtotal(items)
    d = discount(s, code)
    return round((s - d) * (1 + tax), 2)
